function relu(a) { return a.map(v => v > 0 ? v : 0); }

function softmax(a) {
  const m = Math.max(...a);
  const e = a.map(v => Math.exp(v - m));
  const s = e.reduce((x,y) => x+y, 0);
  return e.map(v => v/s);
}

function normalizeLandmarks(lm) {
  const wx = lm[0].x, wy = lm[0].y;
  const pts = lm.map(l => [l.x - wx, l.y - wy]);
  let mx = 0;
  for (const p of pts) {
    if (Math.abs(p[0]) > mx) mx = Math.abs(p[0]);
    if (Math.abs(p[1]) > mx) mx = Math.abs(p[1]);
  }
  if (mx < 1e-6) mx = 1e-6;
  const flat = [];
  for (const p of pts) flat.push(p[0]/mx, p[1]/mx);
  return flat;
}

function predictSign(landmarks) {
  let x = normalizeLandmarks(landmarks);
  const L = SIGN_MODEL.layers;
  for (let i = 0; i < L.length; i++) {
    const W = L[i].W, b = L[i].b;
    x = b.map((bi, j) => bi + x.reduce((s, xi, k) => s + W[k][j] * xi, 0));
    x = i < L.length - 1 ? relu(x) : softmax(x);
  }
  let mi = 0;
  for (let i = 1; i < x.length; i++) if (x[i] > x[mi]) mi = i;
  return { label: SIGN_MODEL.classes[mi], confidence: x[mi], probs: x };
}
